// для которых слайд важен (маршруты по креслам на сайте).
import { MODEL, r0, r1, bn } from './model.mjs';
import * as D from './data.mjs';

const sc = MODEL.scen;
const SC = { n: D.SCORECARD.length, ahead: D.SCORECARD.filter((r) => r.v === 'ahead').length };
// 1 слайд, 2 слайда, 5 слайдов
export const plural = (n, one, few, many) => { const a = n % 100, b = n % 10; return a > 10 && a < 20 ? many : b === 1 ? one : b > 1 && b < 5 ? few : many; };
const b = sc.base;
export const SECTIONS = [
  { id: 'open', t: 'Открытие' },
  { id: 'view', t: 'Взгляд «Моторики»' },
  { id: 'value', t: 'Бизнес-эффект' },
  { id: 'we', t: 'Что приносит MOTUS Lab' },
  { id: 'model', t: 'Как работаем' },
  { id: 'wp', t: 'Пакеты работ' },
  { id: 'plan', t: 'План и пилот' },
  { id: 'trust', t: 'Доверие и риски' },
  { id: 'next', t: 'Решения' },
];
const ALL = ['ceo', 'cfo', 'product', 'digital', 'rnd', 'med', 'ops', 'reg'];

// Числа эффекта в текстах пакетов работ — из модели
const fill = (s) => s.replace('{ret}', r0(b.retained)).replace('{l1}', r0(b.l1[4])).replace('{doc}', r0(b.docHoursSaved))
  .replace('{visits}', r0(b.visits)).replace('{days}', String(b.pathDays)).replace('{cash}', r0(b.cashPulled)).replace('{fte}', r1(b.onboardFte));
export const WP_EFFECT = Object.fromEntries(D.WPS.map((w) => [w.id, fill(w.eff)]));

const wp = (id) => D.WPS.find((w) => w.id === id);
const wpSlide = (id, ch, notes, src, core = false) => ({ sec: 'wp', layout: 'wp', core, ch, kicker: `${id} · трек «${D.TRACKS.find((t) => t.id === wp(id).tr).t}»`, title: wp(id).t, data: { id }, notes, src });

